const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const graph = Array.from({ length: n }, () => []);
const to = [], cap = [];
function addEdge(u, v, c) {
  graph[u].push(to.length); to.push(v); cap.push(c);
  graph[v].push(to.length); to.push(u); cap.push(0);
}
let pos = 2;
for (let i = 0; i < m; i++) { addEdge(tok[pos] - 1, tok[pos + 1] - 1, tok[pos + 2]); pos += 3; }
const s = 0, t = n - 1;
let flow = 0;
for (;;) {
  const level = new Array(n).fill(-1);
  level[s] = 0;
  const queue = [s];
  for (let h = 0; h < queue.length; h++) {
    const u = queue[h];
    for (const e of graph[u]) {
      if (cap[e] > 0 && level[to[e]] < 0) { level[to[e]] = level[u] + 1; queue.push(to[e]); }
    }
  }
  if (level[t] < 0) break;
  const it = new Array(n).fill(0);
  const dfs = (u, f) => {
    if (u === t) return f;
    while (it[u] < graph[u].length) {
      const e = graph[u][it[u]], v = to[e];
      if (cap[e] > 0 && level[v] === level[u] + 1) {
        const d = dfs(v, Math.min(f, cap[e]));
        if (d > 0) { cap[e] -= d; cap[e ^ 1] += d; return d; }
      }
      it[u]++;
    }
    return 0;
  };
  for (;;) {
    const pushed = dfs(s, Infinity);
    if (pushed === 0) break;
    flow += pushed;
  }
}
console.log(String(flow));

