import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static int[] to, level, it;
    static long[] cap;
    static ArrayList<Integer>[] graph;
    static int edges = 0, t;

    static void addEdge(int u, int v, long c) {
        graph[u].add(edges); to[edges] = v; cap[edges++] = c;
        graph[v].add(edges); to[edges] = u; cap[edges++] = 0;
    }

    static long dfs(int u, long f) {
        if (u == t) return f;
        while (it[u] < graph[u].size()) {
            int e = graph[u].get(it[u]);
            int v = to[e];
            if (cap[e] > 0 && level[v] == level[u] + 1) {
                long d = dfs(v, Math.min(f, cap[e]));
                if (d > 0) {
                    cap[e] -= d;
                    cap[e ^ 1] += d;
                    return d;
                }
            }
            it[u]++;
        }
        return 0;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        to = new int[2 * m];
        cap = new long[2 * m];
        for (int i = 0; i < m; i++) {
            in.nextToken(); int u = (int) in.nval - 1;
            in.nextToken(); int v = (int) in.nval - 1;
            in.nextToken(); long c = (long) in.nval;
            addEdge(u, v, c);
        }
        int s = 0;
        t = n - 1;
        long flow = 0;
        level = new int[n];
        it = new int[n];
        while (true) {
            Arrays.fill(level, -1);
            level[s] = 0;
            ArrayDeque<Integer> dq = new ArrayDeque<>();
            dq.add(s);
            while (!dq.isEmpty()) {
                int u = dq.poll();
                for (int e : graph[u]) {
                    if (cap[e] > 0 && level[to[e]] < 0) {
                        level[to[e]] = level[u] + 1;
                        dq.add(to[e]);
                    }
                }
            }
            if (level[t] < 0) break;
            Arrays.fill(it, 0);
            long pushed;
            while ((pushed = dfs(s, Long.MAX_VALUE)) > 0) flow += pushed;
        }
        System.out.println(flow);
    }
}

