#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n, m, s, t;
vector<int> to_, level_, it_;
vector<ll> cap_;
vector<vector<int>> graph_;
void add_edge(int u, int v, ll c) {
    graph_[u].push_back(to_.size()); to_.push_back(v); cap_.push_back(c);
    graph_[v].push_back(to_.size()); to_.push_back(u); cap_.push_back(0);
}
ll dfs(int u, ll f) {
    if (u == t) return f;
    for (int& i = it_[u]; i < (int)graph_[u].size(); i++) {
        int e = graph_[u][i], v = to_[e];
        if (cap_[e] > 0 && level_[v] == level_[u] + 1) {
            ll d = dfs(v, min(f, cap_[e]));
            if (d > 0) { cap_[e] -= d; cap_[e ^ 1] += d; return d; }
        }
    }
    return 0;
}
int main() {
    scanf("%d %d", &n, &m);
    graph_.assign(n, {});
    for (int i = 0; i < m; i++) {
        int u, v;
        ll c;
        scanf("%d %d %lld", &u, &v, &c);
        add_edge(u - 1, v - 1, c);
    }
    s = 0; t = n - 1;
    ll flow = 0;
    while (true) {
        level_.assign(n, -1);
        level_[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int e : graph_[u])
                if (cap_[e] > 0 && level_[to_[e]] < 0) { level_[to_[e]] = level_[u] + 1; q.push(to_[e]); }
        }
        if (level_[t] < 0) break;
        it_.assign(n, 0);
        ll pushed;
        while ((pushed = dfs(s, LLONG_MAX)) > 0) flow += pushed;
    }
    printf("%lld\n", flow);
    return 0;
}
